-- Insert Quiz Questions for Lesson: Create the Thank-You Page

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 8 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 8 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'create-thank-you-page' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson create-thank-you-page not found in module 8';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the main purpose of a thank-you page?', 
    '["To end the interaction","To confirm the submission and tell the lead what happens next","To sell them something immediately","To collect more information"]'::jsonb,
    'To confirm the submission and tell the lead what happens next',
    'The thank-you page confirms the form was submitted successfully and sets expectations for what happens next, building trust and reducing anxiety.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you include on a thank-you page?', 
    '["A complex navigation menu","Confirmation message, expectations, and optional next step","A request for payment","Nothing, keep it blank"]'::jsonb,
    'Confirmation message, expectations, and optional next step',
    'A good thank-you page includes: a confirmation message, expectations about what happens next (and when), and optionally one next step to continue engagement.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you tell people to check spam folders?', 
